INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷一百十六", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/716a3d9ea101493ffb96bbdc98041c65d71f2fd6/content/books/zizhi-tongjian/vol-293/year-0956/part-01/sources/library/jiuwudaishi-116-march-956/source.txt", "note": "《旧五代史》卷一百十六，段落 jiu-wudaishi-205deb4a7860-p002748；EPUB电子本，纸本及异文待核", "id": "f1bed893-849b-56a4-8ac1-ca7e289e131e"}, {"title": "宋史·巻二百五十", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/716a3d9ea101493ffb96bbdc98041c65d71f2fd6/content/books/zizhi-tongjian/vol-293/year-0956/part-01/sources/library/songshi-250-wangshenqi-identity/source.txt", "note": "《宋史》巻二百五十，段落 songshi-9c6e46fee832-p057184；EPUB电子本，纸本及异文待核", "id": "f732e594-6f19-5d3f-ae00-bd7f51aedf56"}, {"title": "宋史·巻二百五十", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/716a3d9ea101493ffb96bbdc98041c65d71f2fd6/content/books/zizhi-tongjian/vol-293/year-0956/part-01/sources/library/songshi-250-wangshenqi-shuzhou/source.txt", "note": "《宋史》巻二百五十，段落 songshi-9c6e46fee832-p057185；EPUB电子本，纸本及异文待核", "id": "a02bb309-6fb4-5e6d-b536-099e97d681e4"}, {"title": "宋史·巻二百五十九", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/716a3d9ea101493ffb96bbdc98041c65d71f2fd6/content/books/zizhi-tongjian/vol-293/year-0956/part-01/sources/library/songshi-259-zhangqiong-identity/source.txt", "note": "《宋史》巻二百五十九，段落 songshi-9c6e46fee832-p057938；EPUB电子本，纸本及异文待核", "id": "7bf8b1bc-f234-5de0-801e-4fc417180889"}, {"title": "宋史·巻二百五十九", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/716a3d9ea101493ffb96bbdc98041c65d71f2fd6/content/books/zizhi-tongjian/vol-293/year-0956/part-01/sources/library/songshi-259-zhangqiong-shield/source.txt", "note": "《宋史》巻二百五十九，段落 songshi-9c6e46fee832-p057939；EPUB电子本，纸本及异文待核", "id": "c0cb2ce8-19b5-5b05-9a3c-bd48c944109c"}, {"title": "资治通鉴·后周纪四", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/716a3d9ea101493ffb96bbdc98041c65d71f2fd6/content/books/zizhi-tongjian/vol-293/year-0956/part-01/sources/library/tongjian-293-956-march-opening/source.txt", "note": "《资治通鉴》后周纪四，段落 zizhi-tongjian-a63549944a71-p003475；电子底本待考，分段待核", "id": "7aa67de9-08ee-52d7-b5ed-85e2e35a19bc"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "柴荣", "aliases": ["郭荣", "柴榮", "郭榮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本姓柴，950年《资治通鉴》以郭荣记名，任贵州刺史、天雄牙内都指挥使。父亲柴守礼是郭威妻子柴氏的兄长，郭威在尚无儿子时收养他。《新五代史》记他幼年跟随姑母在郭威家成长。《旧五代史》的任职纪年与通鉴不同，分别保留。", "biography": null, "status": "draft", "id": "697c1a4f-b373-5a78-8b47-330fe349a424"}, {"name": "赵匡胤", "aliases": ["趙匡胤"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周宿卫将领，后来成为宋太祖。954年高平之战右军溃逃后，与张永德分率两翼反击北汉军。《宋史》本纪印证其率同列冲锋的记载。生卒年留待相应史料补录。", "biography": null, "status": "draft", "id": "ce0fe2a6-d446-50c7-b968-4245fd9693ad"}, {"name": "张琼", "aliases": ["張瓊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "馆陶人，赵匡胤麾下牙将。956年攻寿春时，赵匡胤乘皮船入壕遭弩射，张琼以身体遮护，被射中腿部，重伤后恢复。《宋史》也记大名馆陶籍贯及护救经过，未把死而复苏当作当年永久死亡。", "biography": null, "status": "draft", "id": "57466dc2-1fec-5f24-9c08-c0ba77d8be62"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "孙晟", "aliases": ["孫晟", "孙凤", "孫鳳", "孙忌", "孫忌"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷276天成二年条所见人物：孙晟，判官、劝反者。", "biography": null, "status": "draft", "id": "38c30b43-89f4-5133-8970-38f2fb8f157e"}, {"name": "王崇质", "aliases": ["王崇質"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐礼部尚书。956年三月奉李璟命与司空孙晟一起向后周奉表求和。生卒年未载。", "biography": null, "status": "draft", "id": "45e5f866-09d5-538f-b98c-ba31c3939853"}, {"name": "冯延巳", "aliases": ["馮延巳", "冯延己", "馮延己", "冯延已"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐官员，曾任驾部郎中、齐王元帅府常书记。《资治通鉴》本段作冯延己及延已，《新五代史》作冯延巳；据同一南唐政局、陈觉及常梦锡等对应关系校核为同人，展示采用冯延巳，原文异体保留。生卒年尚未核。", "biography": null, "status": "draft", "id": "0b3ed4d7-1a4c-50a5-ad65-aee4b82089ba"}, {"name": "林延遇", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：林延遇，闽清宦者、国信事务受命者。", "biography": null, "status": "draft", "id": "b5a0d45a-e4ba-5230-bd2f-56bced660fbf"}, {"name": "龚澄枢", "aliases": ["龔澄樞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "番禺人，南汉内给事。956年林延遇病重时推荐其代任，刘弘熙随后任其知承宣院及内侍省。生卒年及后续权势经历待按年代补录。", "biography": null, "status": "draft", "id": "aa5dc218-7d09-572f-93d5-41b8a0cb2575"}, {"name": "刘弘熙", "aliases": ["劉弘熙", "刘洪熙", "劉洪熙", "刘晟", "劉晟"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：刘弘熙，获封王爵之子。", "biography": null, "status": "draft", "id": "b67079e8-6ec8-5150-9451-5b3ce7983fec"}, {"name": "何超（后周光州招安巡检使）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周光、舒、黄招安巡检使、行光州刺史。956年三月率安随申蔡兵攻光州，奏报张承翰带城归降。与943年后晋左飞龙使、暂掌单州的同名何超暂无完整连续履历证据，暂分档保存。", "biography": null, "status": "draft", "id": "4669661b-d295-53c5-a296-433fda3f0605"}, {"name": "张绍", "aliases": ["張紹"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐光州刺史。956年三月周军来攻时放弃城池逃走。生卒年未载。", "biography": null, "status": "draft", "id": "29e29822-b2e5-5ba0-9195-e861f4b7f513"}, {"name": "张承翰", "aliases": ["張承翰"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐光州都监。956年三月带光州归降后周，《旧五代史》还记随后授集州刺史。生卒年未载。", "biography": null, "status": "draft", "id": "7dbfc341-08c9-5418-a74f-77fe217002b0"}, {"name": "郭令图", "aliases": ["郭令圖"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周行舒州刺史。956年三月攻取舒州后，被舒州人驱逐；王审琦夜袭恢复后，郭令图得回城。生卒年未载。", "biography": null, "status": "draft", "id": "119973d0-2d51-537e-aa8c-ade51c24d2eb"}, {"name": "李福（南唐蕲州将）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐蕲州将领。956年三月杀死知州王承巂，带州归降后周。与904年条所见同名李福暂无同人证据，暂分档保存。", "biography": null, "status": "draft", "id": "c3ba3dce-b1aa-5c12-849e-5056a26136c0"}, {"name": "王承巂", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": 956, "description": "南唐蕲州知州。956年三月被当地将领李福杀死，随后蕲州归降后周。生年未载。", "biography": null, "status": "draft", "id": "f4b9026f-5bc6-5676-bd01-4fa3a32f0cf3"}, {"name": "齐藏珍", "aliases": ["齊藏珍"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后汉将军。948年正月与王景崇率禁军迎接回鹘贡使并经略关西。其后建议杀赵思绾，王景崇没有听从。生卒年未载。", "biography": null, "status": "draft", "id": "654b2549-6bd7-5790-80f4-0c95bd3781b3"}, {"name": "李彦頵", "aliases": ["李彥頵"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周彰武军留后。956年其治下民众及羌胡因其侵刻起事，柴荣召其回朝；《旧五代史》称延州留后，补记其与都监阎绾镇压，并杀酋帅十人。生卒年未载。", "biography": null, "status": "draft", "id": "a1fe4848-6c3b-5dd2-a366-9a0f5595100d"}, {"name": "王审琦", "aliases": ["王審琦"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "洛阳人，后周铁骑都指挥使，字仲宝。956年舒州人逐郭令图后，选轻骑夜袭恢复舒州。《宋史》记其先世辽西、后迁洛阳及早年在郭威军中履历，生卒年待后续补录。", "biography": null, "status": "draft", "id": "26929070-4b43-5b96-9683-d93666d18723"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "柴荣察看水寨，在淝桥取石运往寨中，命随从各携一石", "start_year": 956, "end_year": 956, "time_original": "956年三月甲午朔", "dynasty": "五代十国", "description": "柴荣察看水寨，在淝桥取石运往寨中，命随从各携一石。", "phases": [], "location_name": "淝桥至寿州水寨", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "b5bb2a8d-db86-594d-a226-3464c103a9e7"}, {"title": "赵匡胤乘皮船进入寿春壕中，遭城上连弩射击", "start_year": 956, "end_year": 956, "time_original": "956年三月寿春围攻期间，具体日未载", "dynasty": "五代十国", "description": "赵匡胤乘皮船进入寿春壕中，遭城上连弩射击。", "phases": [], "location_name": "寿春城壕", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "92c36fd9-6a39-565d-859a-dff4747cf951"}, {"title": "张琼以身护赵匡胤，被弩箭射中腿部，重伤后苏醒", "start_year": 956, "end_year": 956, "time_original": "956年三月寿春壕中受射时，具体日未载", "dynasty": "五代十国", "description": "张琼以身护赵匡胤，被弩箭射中腿部，重伤后苏醒。", "phases": [], "location_name": "寿春城壕", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "46df27de-339e-575b-85b3-a0b424b40d63"}, {"title": "张琼饮酒后让人破骨取出箭镞，史书称其镇定", "start_year": 956, "end_year": 956, "time_original": "956年寿春受伤之后，具体处置日未载", "dynasty": "五代十国", "description": "《通鉴》记箭镞卡在骨中不能拔出，张琼饮酒后让人破骨取出，流血数升而神色自若。这是史书中的治疗经过及勇毅描写，原书的计量和效果不当作现代医学测量。", "phases": [], "location_name": "寿春战场附近，具体地点未载", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "672f0f1c-8990-56b0-95f9-c32ad9bb173c"}, {"title": "李璟升孙晟为司空，派他与王崇质奉表求和并献财物", "start_year": 956, "end_year": 956, "time_original": "956年三月奉表出使，具体派遣日未单列", "dynasty": "五代十国", "description": "李璟任孙晟为司空，与礼部尚书王崇质共同奉表，表示愿仿效吴越、湖南奉后周正朔、守土为外臣，请求停止征伐；献金千两、银十万两、罗绮二千匹。奉表表达臣服愿望，不是双方已经缔结和约。", "phases": [], "location_name": "南唐至后周行在", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "13bc1fff-7264-51b1-bae0-6ec49013537c"}, {"title": "孙晟对冯延巳说出使本当由左相承担，但自己不能负先帝", "start_year": 956, "end_year": 956, "time_original": "956年三月孙晟出使之前，具体日未载", "dynasty": "五代十国", "description": "孙晟对冯延巳说出使本当由左相承担，但自己不能负先帝。", "phases": [], "location_name": "南唐朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "6c587677-1bec-595e-af20-67f79af5c053"}, {"title": "孙晟途中对王崇质说自己决不负永陵，并劝其自谋", "start_year": 956, "end_year": 956, "time_original": "956年三月出使途中，具体夜晚未载", "dynasty": "五代十国", "description": "孙晟途中对王崇质说自己决不负永陵，并劝其自谋。", "phases": [], "location_name": "出使途中，具体地点未载", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "16c3b846-dc5a-5f93-8f8a-9a10b7b00bd7"}, {"title": "林延遇去世，史书记南汉民众相贺", "start_year": 956, "end_year": 956, "time_original": "956年三月乙未", "dynasty": "五代十国", "description": "林延遇去世，史书记南汉民众相贺。", "phases": [], "location_name": "南汉", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "95da8162-13f0-5c65-8dfe-614feee774e6"}, {"title": "林延遇病重时推荐龚澄枢接替自己", "start_year": 956, "end_year": 956, "time_original": "956年三月乙未林延遇死前，具体推荐日未载", "dynasty": "五代十国", "description": "林延遇病重时推荐龚澄枢接替自己。", "phases": [], "location_name": "南汉宫廷", "location_modern_name": null, "location_la