INSERT INTO public.fact_claim (id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status)
SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "柴荣察看水寨，在淝桥取石运往寨中，命随从各携一石。", "citation": "卷293·显德三年（956年三月及相关追述）·zztj-v293-y0956-p001·原文件第6行", "note": "原文：三月，甲午朔，上行视水寨，至淝桥，自取一石，马上持之至寨以供砲，从官过桥者人赍一石。；核对说明：砲在此为攻城投石器，不写成近代火炮；取一石是石块，不换成粮食石或固定重量。", "status": "draft", "id": "6b8cc080-3960-5075-ae83-cf269fdd83cf", "subject_id": "b5bb2a8d-db86-594d-a226-3464c103a9e7", "source_id": "7aa67de9-08ee-52d7-b5ed-85e2e35a19bc"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "956年三月甲午朔", "citation": "卷293·显德三年（956年三月及相关追述）·zztj-v293-y0956-p001·原文件第6行", "note": "原文：三月，甲午朔，上行视水寨，至淝桥，自取一石，马上持之至寨以供砲，从官过桥者人赍一石。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "1c30f532-96b8-51ff-a620-36efebb0561e", "subject_id": "b5bb2a8d-db86-594d-a226-3464c103a9e7", "source_id": "7aa67de9-08ee-52d7-b5ed-85e2e35a19bc"}, {"subject_table": "person", "field_path": "description", "claim_text": "柴荣：亲自携石并要求随从协助运石。", "citation": "卷293·显德三年（956年三月及相关追述）·zztj-v293-y0956-p001·原文件第6行", "note": "原文：三月，甲午朔，上行视水寨，至淝桥，自取一石，马上持之至寨以供砲，从官过桥者人赍一石。；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "68eccc8b-81a5-5b75-b478-65b0b5ca7d85", "subject_id": "697c1a4f-b373-5a78-8b47-330fe349a424", "source_id": "7aa67de9-08ee-52d7-b5ed-85e2e35a19bc"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "柴荣：亲自携石并要求随从协助运石。", "citation": "卷293·显德三年（956年三月及相关追述）·zztj-v293-y0956-p001·原文件第6行", "note": "原文：三月，甲午朔，上行视水寨，至淝桥，自取一石，马上持之至寨以供砲，从官过桥者人赍一石。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "781f64eb-5aef-5daa-9d78-9755518ea7b0", "subject_id": "8530581f-c01b-514d-9826-85d2d3b952b2", "source_id": "7aa67de9-08ee-52d7-b5ed-85e2e35a19bc"}, {"subject_table": "event", "field_path": "description", "claim_text": "赵匡胤乘皮船进入寿春壕中，遭城上连弩射击。", "citation": "卷293·显德三年（956年三月及相关追述）·zztj-v293-y0956-p002·原文件第7行", "note": "原文：太祖皇帝乘皮船入寿春壕中，城上发连弩射之，矢大如屋椽。；核对说明：矢如屋椽为史载形容，不据此制作未经考证的精确武器尺寸。", "status": "draft", "id": "8c798cbf-0be9-552d-bdbc-9a689bc1bad5", "subject_id": "92c36fd9-6a39-565d-859a-dff4747cf951", "source_id": "7aa67de9-08ee-52d7-b5ed-85e2e35a19bc"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "956年三月寿春围攻期间，具体日未载", "citation": "卷293·显德三年（956年三月及相关追述）·zztj-v293-y0956-p002·原文件第7行", "note": "原文：太祖皇帝乘皮船入寿春壕中，城上发连弩射之，矢大如屋椽。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "de740b25-1e85-52dc-a0fc-cd9d76b5dedf", "subject_id": "92c36fd9-6a39-565d-859a-dff4747cf951", "source_id": "7aa67de9-08ee-52d7-b5ed-85e2e35a19bc"}, {"subject_table": "person", "field_path": "description", "claim_text": "赵匡胤：乘皮船入壕受到城上弩射。", "citation": "卷293·显德三年（956年三月及相关追述）·zztj-v293-y0956-p002·原文件第7行", "note": "原文：太祖皇帝乘皮船入寿春壕中，城上发连弩射之，矢大如屋椽。；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "95a8356a-51a4-5d98-ad06-6358581f3a13", "subject_id": "ce0fe2a6-d446-50c7-b968-4245fd9693ad", "source_id": "7aa67de9-08ee-52d7-b5ed-85e2e35a19bc"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "赵匡胤：乘皮船入壕受到城上弩射。", "citation": "卷293·显德三年（956年三月及相关追述）·zztj-v293-y0956-p002·原文件第7行", "note": "原文：太祖皇帝乘皮船入寿春壕中，城上发连弩射之，矢大如屋椽。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "e37f7367-2fd7-5101-aaad-20e109d7f353", "subject_id": "9d3ded1e-40c2-5481-bd7e-5a169b5d6f20", "source_id": "7aa67de9-08ee-52d7-b5ed-85e2e35a19bc"}, {"subject_table": "event", "field_path": "description", "claim_text": "张琼以身护赵匡胤，被弩箭射中腿部，重伤后苏醒。", "citation": "卷293·显德三年（956年三月及相关追述）·zztj-v293-y0956-p002·原文件第7行", "note": "原文：牙将馆陶张琼遽以身蔽之，矢中琼髀，死而复苏。；核对说明：死而复苏作为重伤后恢复的叙述保存，不填写张琼死亡年956；两书后续仍有其活动。", "status": "draft", "id": "969e2b62-55e1-51e8-89fb-a9b4cb86200e", "subject_id": "46df27de-339e-575b-85b3-a0b424b40d63", "source_id": "7aa67de9-08ee-52d7-b5ed-85e2e35a19bc"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "956年三月寿春壕中受射时，具体日未载",